<?php
require_once __DIR__.'/config/app.php';require_once __DIR__.'/config/koneksi.php';require_login();$pageTitle='Absensi';$role=current_user()['role'];$sid=(int)(current_user()['siswa_id']??0);$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';if($a==='save'){ $student=$role==='admin'?(int)($_POST['siswa_id']??0):$sid;$date=$_POST['tanggal']??'';$status=$_POST['status']??'';$catatan=trim($_POST['catatan']??'');
 if(!$student||!$date||!in_array($status,['Hadir','Izin','Sakit','Alpa'],true))$errors[]='Siswa, tanggal, dan status wajib dipilih.';
 if(!$errors){$q=$pdo->prepare("INSERT INTO absensi(siswa_id,tanggal,status,catatan) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),catatan=VALUES(catatan)");$q->execute([$student,$date,$status,$catatan]);flash('success','Absensi berhasil disimpan.');redirect('absensi.php');}}}
$students=$pdo->query("SELECT id,nama FROM siswa ORDER BY nama")->fetchAll();$dateFilter=$_GET['tanggal']??'';$sql="SELECT a.*,s.nama FROM absensi a JOIN siswa s ON s.id=a.siswa_id WHERE 1";$params=[];if($role==='siswa'){$sql.=" AND a.siswa_id=?";$params[]=$sid;}if($dateFilter!==''){$sql.=" AND a.tanggal=?";$params[]=$dateFilter;}$sql.=" ORDER BY a.tanggal DESC,a.id DESC";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();
$q=$pdo->prepare("SELECT COUNT(*) total,SUM(status='Hadir') hadir FROM absensi WHERE siswa_id=?");$q->execute([$role==='siswa'?$sid:0]);$mine=$q->fetch();include __DIR__.'/partials/header.php';?>
<div class="page-head"><div><h1>Absensi PKL</h1><div class="muted">Catat kehadiran siswa per tanggal.</div></div></div><?php foreach($errors as $x):?><div class="alert danger"><?=e($x)?></div><?php endforeach;?>
<div class="card"><h3>Input Absensi</h3><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="form-grid"><?php if($role==='admin'):?><div class="field"><label>Siswa *</label><select name="siswa_id" required><option value="">Pilih siswa</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=e($s['nama'])?></option><?php endforeach;?></select></div><?php endif;?><div class="field"><label>Tanggal *</label><input type="date" name="tanggal" required value="<?=date('Y-m-d')?>"></div><div class="field"><label>Status *</label><select name="status" required><option value="">Pilih status</option><?php foreach(['Hadir','Izin','Sakit','Alpa'] as $st):?><option><?=e($st)?></option><?php endforeach;?></select></div><div class="field"><label>Catatan</label><input name="catatan" placeholder="Opsional"></div></div><div class="form-actions"><button class="btn">Simpan Absensi</button></div></form></div>
<div class="card"><form class="filters"><input type="date" name="tanggal" value="<?=e($dateFilter)?>"><button class="btn">Filter tanggal</button><a class="btn secondary" href="absensi.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Tanggal</th><?php if($role==='admin'):?><th>Siswa</th><?php endif;?><th>Status</th><th>Catatan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><?php if($role==='admin'):?><td><?=e($r['nama'])?></td><?php endif;?><td><span class="badge <?= $r['status']==='Hadir'?'success':($r['status']==='Alpa'?'danger':'warning')?>"><?=e($r['status'])?></span></td><td><?=e($r['catatan'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="empty">Belum ada data absensi.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/partials/footer.php';?>
